input.command:
gh api graphql -f query='
query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){
    pullRequest(number:$pr){
      reviewThreads(first:100){
        nodes{
          id isResolved isOutdated path line
          comments(first:30){nodes{author{login} url body}}
        }
      }
    }
  }
}' -F owner=malpercio-dev -F repo=ezpds -F pr=311 | jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | {id, path, line, isOutdated, comments: [.comments.nodes[] | {author: .author.login, body}]}]'
